-- Typed tables for every kind of record JamsNET saves.
-- The app keeps saving to public.documents. A trigger copies each saved document into matching
-- typed tables, one column per field, so data can be queried, filtered, exported and reported on.
-- Typed tables are read-only copies: change data in the app. Fields not listed as columns are kept
-- in each row's "extra" column, so nothing is lost. If a document can't be copied, the app's save
-- still succeeds and the problem is logged in private.sync_errors.
-- The table list lives in private.typed_tables (generated by supabase/tools/gen_typed_tables.py).

-- conversion helpers: never raise, return null when a value doesn't fit the column
create or replace function private.j_text(v jsonb) returns text language sql immutable set search_path = '' as $$
  select case when v is null or jsonb_typeof(v) = 'null' then null when jsonb_typeof(v) = 'string' then v #>> '{}' else v::text end $$;
create or replace function private.j_num(v jsonb) returns numeric language plpgsql immutable set search_path = '' as $$
begin
  if v is null or jsonb_typeof(v) = 'null' then return null; end if;
  if jsonb_typeof(v) = 'number' then return (v #>> '{}')::numeric; end if;
  if jsonb_typeof(v) = 'string' and btrim(v #>> '{}') ~ '^-?[0-9]+(\.[0-9]+)?$' then return btrim(v #>> '{}')::numeric; end if;
  return null;
exception when others then return null;
end $$;
create or replace function private.j_bool(v jsonb) returns boolean language sql immutable set search_path = '' as $$
  select case when v is null then null when jsonb_typeof(v) = 'boolean' then (v #>> '{}')::boolean
              when lower(v #>> '{}') in ('true','yes','y','1','on') then true
              when lower(v #>> '{}') in ('false','no','n','0','off') then false else null end $$;
create or replace function private.j_date(v jsonb) returns date language plpgsql immutable set search_path = '' as $$
begin
  if v is null or jsonb_typeof(v) <> 'string' or (v #>> '{}') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}' then return null; end if;
  return left(v #>> '{}', 10)::date;
exception when others then return null;
end $$;
create or replace function private.j_ts(v jsonb) returns timestamptz language plpgsql immutable set search_path = '' as $$
begin
  if v is null or jsonb_typeof(v) = 'null' then return null; end if;
  if jsonb_typeof(v) = 'number' then return to_timestamp((v #>> '{}')::double precision / 1000); end if;
  if jsonb_typeof(v) = 'string' and (v #>> '{}') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}' then return (v #>> '{}')::timestamptz; end if;
  return null;
exception when others then return null;
end $$;
create or replace function private.j_arr(v jsonb) returns setof jsonb language sql immutable set search_path = '' as $$
  select x from jsonb_array_elements(case when jsonb_typeof(v) = 'array' then v else '[]'::jsonb end) as t(x) $$;
-- some documents are stored as {"json": "<text>"}; this returns the real JSON either way
create or replace function private.doc_value(d jsonb) returns jsonb language plpgsql immutable set search_path = '' as $$
begin
  if d ? 'json' and jsonb_typeof(d -> 'json') = 'string' then return (d ->> 'json')::jsonb; end if;
  return d;
exception when others then return null;
end $$;

create table private.sync_errors (
  id bigint generated always as identity primary key,
  path text, message text, at timestamptz not null default now()
);

-- one row per typed table
create table private.typed_tables (
  name text primary key,
  parent text,            -- for child tables: the table whose records hold them
  doc_regex text not null,-- which saved documents feed this table
  arr_path text[],        -- where the records are in the document; null = the document is the record
  child_path text[],      -- for child tables: the list inside each parent record
  key text,               -- field holding the record's id (null: numbered lines)
  parent_col text,        -- column linking a child row to its parent
  net boolean not null default false,
  admin_only boolean not null default false,
  comment text,
  cols jsonb not null,    -- [[field path, type, column name], ...]; type: t n b j d ts
  insert_sql text         -- built by private.build_typed_tables()
);

create or replace function private.build_typed_tables() returns void
language plpgsql set search_path = '' as $$
declare r record; c jsonb; parent record; ddl text; ins text; names text[]; vals text[]; excl text[]; src text; e text; frm text; ty text; expr text;
begin
  for r in select * from private.typed_tables order by parent nulls first, name loop
    names := array['source_path']; vals := array['$1'];
    ddl := format('create table if not exists public.%I (row_id bigint generated always as identity primary key, source_path text not null', r.name);
    if r.net then ddl := ddl || ', network_id text not null'; names := names || 'network_id'::text; vals := vals || '$4'::text; end if;
    if r.parent is not null then
      select * into parent from private.typed_tables where name = r.parent;
      ddl := ddl || format(', %I text', r.parent_col); names := names || r.parent_col::text;
      e := 'c';
      if parent.arr_path is null then
        vals := vals || '$3'::text;
        frm := format('from private.j_arr($2 #> %L) with ordinality as y(c, ord)', r.child_path);
      else
        vals := vals || format('private.j_text(p #> %L)', array[parent.key]);
        frm := format('from private.j_arr($2 #> %L) as x(p), private.j_arr(p #> %L) with ordinality as y(c, ord)', parent.arr_path, r.child_path);
      end if;
    else
      e := 'e';
      frm := case when r.arr_path is null then 'from (select $2 as e) as x' else format('from private.j_arr($2 #> %L) as x(e)', r.arr_path) end;
    end if;
    if r.key is not null or r.parent is null then
      ddl := ddl || ', id text'; names := names || 'id'::text;
      vals := vals || case when r.parent is null and r.arr_path is null then '$3' else format('private.j_text(%s #> %L)', e, array[r.key]) end;
    else
      ddl := ddl || ', line_no integer not null'; names := names || 'line_no'::text; vals := vals || 'ord::integer'::text;
    end if;
    excl := array_remove(array[r.key], null);
    for c in select * from jsonb_array_elements(r.cols) loop
      ty := c ->> 1;
      ddl := ddl || format(', %I %s', c ->> 2, case ty when 't' then 'text' when 'n' then 'numeric' when 'b' then 'boolean' when 'j' then 'jsonb' when 'd' then 'date' else 'timestamptz' end);
      src := format('%s #> %L', e, string_to_array(c ->> 0, '.'));
      expr := case ty when 't' then format('private.j_text(%s)', src) when 'n' then format('private.j_num(%s)', src) when 'b' then format('private.j_bool(%s)', src)
                      when 'j' then format('nullif(%s, %L::jsonb)', src, 'null') when 'd' then format('private.j_date(%s)', src) else format('private.j_ts(%s)', src) end;
      names := names || (c ->> 2)::text; vals := vals || expr::text;
      excl := excl || split_part(c ->> 0, '.', 1)::text;
    end loop;
    -- child lists are stored in their own tables, so leave them out of "extra"
    excl := excl || coalesce((select array_agg(t.child_path[1]) from private.typed_tables t where t.parent = r.name), '{}');
    ddl := ddl || ', extra jsonb, synced_at timestamptz not null default now())';
    execute ddl;
    execute format('comment on table public.%I is %L', r.name, r.comment || ' Kept in step with the app automatically; read-only.');
    execute format('create index if not exists %I on public.%I (source_path)', r.name || '_source_path_idx', r.name);
    if r.parent is not null then execute format('create index if not exists %I on public.%I (%I)', r.name || '_parent_idx', r.name, r.parent_col); end if;
    if r.net then execute format('create index if not exists %I on public.%I (network_id)', r.name || '_network_idx', r.name); end if;
    execute format('alter table public.%I enable row level security', r.name);
    execute format('drop policy if exists %I on public.%I', 'Team members read this', r.name);
    execute format('create policy %I on public.%I for select to authenticated using (%s)', 'Team members read this', r.name,
                   case when r.admin_only then '(select private.is_admin())' else '(select private.is_member())' end);
    execute format('grant select on public.%I to authenticated', r.name);
    names := names || 'extra'::text;
    vals := vals || format('nullif(case when jsonb_typeof(%1$s) = %2$L then %1$s - %3$L::text[] else jsonb_build_object(%4$L, %1$s) end, %5$L::jsonb)', e, 'object', excl, 'value', '{}');
    ins := format('insert into public.%I (%s) select %s %s', r.name,
                  (select string_agg(format('%I', n), ', ') from unnest(names) n), array_to_string(vals, ', '), frm);
    update private.typed_tables set insert_sql = ins where name = r.name;
  end loop;
end $$;
revoke all on function private.build_typed_tables() from public;

-- copy one saved document into its typed tables (d is null when the document was deleted)
create or replace function private.sync_document(p text, d jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare v jsonb := private.doc_value(d); doc_id text := split_part(p, '/', array_length(string_to_array(p, '/'), 1));
        net_id text := case when p like 'netline/v1/projects/%' then split_part(p, '/', 4) end; r record;
begin
  for r in select name, insert_sql from private.typed_tables where p ~ doc_regex order by parent nulls first, name loop
    begin
      execute format('delete from public.%I where source_path = $1', r.name) using p;
      if v is not null then execute r.insert_sql using p, v, doc_id, net_id; end if;
    exception when others then
      insert into private.sync_errors (path, message) values (p, r.name || ': ' || sqlerrm);
    end;
  end loop;
end $$;
revoke all on function private.sync_document(text, jsonb) from public;

create or replace function private.on_document_change() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'DELETE' then
    perform private.sync_document(old.path, null);
  else
    if tg_op = 'UPDATE' and old.path <> new.path then perform private.sync_document(old.path, null); end if;
    perform private.sync_document(new.path, new.data);
  end if;
  return null;
end $$;
revoke all on function private.on_document_change() from public;

create trigger documents_sync_typed_tables
  after insert or update or delete on public.documents
  for each row execute function private.on_document_change();
